insert into public.site_settings (id, payload, review_status) values ('main', '{"hours":"7:00 AM – 12:00 AM","phone":"+63 (0)00 000 0000","email":"email@placeholder.com","address":"23rd Floor (SP), City Garden Hotel Makati, Makati Ave. corner Durban St., Makati City 7870","opentable":"https://www.opentable.com.au/r/encima-roofdeck-restaurant-makati-reservations-makati-city?restref=327572&lang=en-AU&ot_source=Restaurant%20website&ot_campaign=digital_menu","social":{"facebook":"#","instagram":"#","tiktok":"#"},"heroKick":"Rooftop dining · 23rd floor","heroLead":"Mexican- and Spanish-inspired plates, wine, cocktails and coffee, high above Makati.","storyTitle":"Above the city, around the table","storyP1":"Encima means \"above\" in Spanish, and that is where you will find us: on the 23rd floor of City Garden Hotel Makati, with the skyline at your table.","storyP2":"Our kitchen cooks Mexican- and Spanish-inspired plates alongside pasta, pizza and steaks, made for sharing. Pair them with wine, a signature cocktail or a good cup of coffee.","storyP3":"Open every day from morning until midnight."}'::jsonb, 'approved');
